import { NotFoundError } from "../domain/errors";
import { ProjectRepository } from "../domain/project-repository";
import { TaskFilter, TaskRepository } from "../domain/task-repository";
import { parseTaskStatus } from "../domain/task-status";
import { ListProjectTasksInput, TaskDto, toTaskDto } from "./dtos";

export class ListProjectTasksUseCase {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
  ) {}

  async execute(input: ListProjectTasksInput): Promise<TaskDto[]> {
    const project = await this.projects.findById(input.projectId);
    if (!project) {
      throw new NotFoundError(`project ${input.projectId} not found`);
    }
    const filter: TaskFilter = {};
    if (input.status !== undefined) {
      filter.status = parseTaskStatus(input.status);
    }
    if (input.assigneeId !== undefined) {
      filter.assigneeId = input.assigneeId;
    }
    const found = await this.tasks.findByProject(project.id, filter);
    return found.map(toTaskDto);
  }
}

