    private readonly tasks: TaskRepository,
  ) {}

  async execute(input: MarkTaskDoneInput): Promise<TaskDto> {
    const task = await this.lookup.getInProject(input.projectId, input.taskId);
    task.markDone();
    await this.tasks.save(task);
    return toTaskDto(task);
